def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n or (n == 0 and len(fields) == 0):
        if i >= n:
            # End of line - add empty field if we haven't started
            if len(fields) == 0:
                fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote or the closing quote
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Must be followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < n and line[i] == ',':
                i += 1
            elif i < n:
                # This shouldn't happen as we break on non-comma
                return None

    return fields

